/**
 * Component: Acode Master - FB &amp; WhatsApp UI Combo
 * Author: @mfuranziza-hamza (https://tailwindflex.com/@mfuranziza-hamza)
 * Source: https://tailwindflex.com/@mfuranziza-hamza/acode-master-fb-whatsapp-ui-combo
 * Attribution: Créé par @mfuranziza-hamza sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function AcodeMasterFbWhatsappUiCombo() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Acode Master - FB & WhatsApp UI Combo</title>

  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
  <style type="text/tailwindcss">
    @tailwind base;
    @tailwind components;
    @tailwind utilities;

    @layer components {
      .btn-primary {
        @apply bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500 hover:from-pink-500 hover:to-yellow-500 text-white px-4 py-2 rounded-full transition duration-500 ease-in-out;
      }
      .nav-icon {
        @apply p-2 text-gray-600 hover:text-blue-600 transition duration-300;
      }
      .animated-bg {
        background: linear-gradient(-45deg, #1e3a8a, #9333ea, #db2777, #facc15);
        background-size: 400% 400%;
        animation: gradientBG 10s ease infinite;
      }
      @keyframes gradientBG {
        0% { background-position: 0% 50%; }
        50% { background-position: 100% 50%; }
        100% { background-position: 0% 50%; }
      }
    }
  </style>
</head>
<body class="bg-gray-50 font-sans">
  <!-- Header -->
  <nav class="fixed top-0 left-0 w-full bg-white shadow z-50">
    <div class="max-w-7xl mx-auto px-4 py-2 flex justify-between items-center">
      <div class="flex items-center space-x-3">
        <img src="data:image/jpeg;base64," alt="Acode Master Logo" class="w-8 h-8 rounded-full">
        <span class="font-bold text-lg text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500 animate-pulse">Acode Master</span>
      </div>
      <div class="hidden md:flex space-x-6">
        <a href="#" class="nav-icon"><i class="fas fa-home"></i></a>
        <a href="#" class="nav-icon"><i class="fas fa-user-friends"></i></a>
        <a href="#" class="nav-icon"><i class="fas fa-video"></i></a>
        <a href="#" class="nav-icon"><i class="fas fa-store"></i></a>
      </div>
      <div class="flex items-center space-x-4">
        <button class="relative nav-icon">
          <i class="fas fa-comments"></i>
          <span class="absolute top-0 right-0 w-4 h-4 bg-red-500 text-xs text-white rounded-full flex items-center justify-center">2</span>
        </button>
        <button class="nav-icon"><i class="fas fa-bell"></i></button>
        <img src="data:image/jpeg;base64," alt="Profile" class="h-8 w-8 rounded-full object-cover">
      </div>
    </div>
  </nav>

  <!-- Sidebar + Chat like WhatsApp -->
  <div class="flex pt-16">
    <!-- Sidebar -->
    <aside class="hidden md:block w-64 bg-white border-r min-h-screen p-4">
      <div class="text-xl font-semibold mb-4">Chats</div>
      <ul class="space-y-2">
        <li class="flex items-center space-x-3 hover:bg-gray-100 p-2 rounded cursor-pointer">
          <img src="data:image/jpeg;base64," class="h-10 w-10 rounded-full" alt="Imano">
          <div>
            <div class="font-medium">Imano</div>
            <div class="text-sm text-gray-500">Hey bro, project iragenda...</div>
          </div>
        </li>
        <li class="flex items-center space-x-3 hover:bg-gray-100 p-2 rounded cursor-pointer">
          <img src="data:image/jpeg;base64," class="h-10 w-10 rounded-full" alt="CodeMaster Team">
          <div>
            <div class="font-medium">CodeMaster Team</div>
            <div class="text-sm text-gray-500">Let's push update tonight</div>
          </div>
        </li>
      </ul>
    </aside>

    <!-- Main Chat Window -->
    <main class="flex-1 bg-gray-100 p-6">
      <div class="bg-white shadow rounded-lg p-4 h-[80vh] flex flex-col">
        <div class="flex-1 overflow-y-auto space-y-4">
          <div class="flex items-start space-x-2">
            <img src="data:image/jpeg;base64," class="h-8 w-8 rounded-full" alt="Imano">
            <div class="bg-gray-200 p-2 rounded">Hello Acode Master!</div>
          </div>
          <div class="flex items-start justify-end space-x-2">
            <div class="animated-bg text-white p-2 rounded">Hey! How can I help?</div>
            <img src="data:image/jpeg;base64," class="h-8 w-8 rounded-full" alt="You">
          </div>
          <div class="flex items-start space-x-2">
            <img src="data:image/jpeg;base64," class="h-8 w-8 rounded-full" alt="Imano">
            <div class="bg-gray-200 p-2 rounded">Can you add an image like this?</div>
          </div>
          <div class="flex items-start justify-end space-x-2">
            <div class="animated-bg text-white p-2 rounded">Yes, done!</div>
            <img src="data:image/jpeg;base64," class="h-8 w-8 rounded-full" alt="You">
          </div>
        </div>
        <div class="mt-4 flex items-center">
          <input type="text" class="flex-1 p-2 border border-gray-300 rounded-full focus:outline-none" placeholder="Type a message...">
          <button class="ml-2 btn-primary"><i class="fas fa-paper-plane"></i></button>
        </div>
      </div>
    </main>
  </div>
</body>
</html>" }} />
  );
}
